import React from 'react';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

/**
 * @internal
 * Bubble Shape Props
 */
export interface BubbleShapeProps {
  active?: boolean;
  color: string;
}
const StyledBubbleOutline = /* @__PURE__ */ styled('div')<{
  $active: boolean;
}>(({ $active }) => ({
  border: $active ? `1px solid ${Colors.Text.Neutral.Default}` : 'none',
  borderRadius: '50%',
}));

const StyledBubbleBorder = /* @__PURE__ */ styled('div')<{
  $color: string;
}>(({ $color }) => ({
  border: `1px solid ${$color}`,
  borderRadius: '50%',
  margin: '1px',
}));

const StyledBubble = /* @__PURE__ */ styled('div')<{
  $color: string;
}>(({ $color }) => ({
  height: '8px',
  width: '8px',
  borderRadius: '50%',
  backgroundColor: $color,
  opacity: 0.4,
}));

export const BubbleShape = ({ active = false, color }: BubbleShapeProps) => {
  return (
    <StyledBubbleOutline $active={active}>
      <StyledBubbleBorder $color={color}>
        <StyledBubble $color={color} />
      </StyledBubbleBorder>
    </StyledBubbleOutline>
  );
};

BubbleShape['displayName'] = 'BubbleShape';
